    const list=await rpc<Project[]>('list_projects');
    const revisions=view==='library'&&selected?await rpc<Revision[]>('history',{sceneId:selected.id}):[];
    const heads=view==='library'&&selected?await rpc<Revision[]>('conflicts',{sceneId:selected.id}):[];
